<template>
  <ResponsiveTableRow class="grid hover:bg-transparent">
    <ResponsiveTableCell
      :cols="cols"
      :cols-sm="colsSm"
      :label="label"
      :class="cn('p-4 whitespace-nowrap align-middle text-sm text-foreground pointer-events-none', props.class)"
      v-bind="delegatedProps"
    >
      <div class="flex items-center justify-center">
        <slot />
      </div>
    </ResponsiveTableCell>
  </ResponsiveTableRow>
</template>

<script setup lang="ts">
import { cn } from '@/components/ui/utils';
import { computed, type HTMLAttributes } from 'vue';

const props = withDefaults(
  defineProps<{
    class?: HTMLAttributes['class'];
    colspan?: number;
    label?: string;
    cols: 1 | 2 | 3 | 4;
    colsSm: 1 | 2 | 3 | 4;
  }>(),
  {
    colspan: 1,
    class: undefined,
    label: undefined,
  }
);

const delegatedProps = computed(() => {
  const { class: _, cols, colsSm, label, ...delegated } = props;

  return delegated;
});
</script>

<style scoped lang="scss"></style>
